mapper.update:
UPDATE mk_referral_evidence_fanout SET status='PROCESSING',lease_owner=#{owner},lease_until=#{until},
  lease_fence=#{nextFence},row_version=#{nextVersion},updated_at=#{now}
  WHERE tenant_id=#{tenant} AND resource_id=#{resource} AND desired_version=#{desired} AND lease_fence=#{fence} AND row_version=#{version}

mapper.select:
SELECT tenantId,participantId,relationId,organizationId,shopId FROM (
 SELECT r.tenant_id AS tenantId,r.participant_id AS participantId,r.relation_id AS relationId,r.organization_id AS organizationId,r.shop_id AS shopId
 FROM mk_referral_relation r WHERE r.tenant_id=#{tenant} AND r.invitee_key=#{subject} AND r.subject_key_version=#{keyVersion}
  AND BINARY r.organization_id=BINARY #{organization} AND BINARY r.shop_id=BINARY #{shop}
 UNION
 SELECT r.tenant_id AS tenantId,r.participant_id AS participantId,r.relation_id AS relationId,r.organization_id AS organizationId,r.shop_id AS shopId
 FROM mk_referral_qualification q JOIN mk_referral_relation r ON r.tenant_id=q.tenant_id AND r.relation_id=q.relation_id AND r.participant_id=q.participant_id
 WHERE q.tenant_id=#{tenant} AND q.evidence_resource_id=#{resource}
) candidate
WHERE relationId>#{cursor}
ORDER BY relationId LIMIT #{limit}

