UPDATE mk_referral_evidence_fanout SET status=#{status},cursor_relation_id=#{cursor},lease_owner=NULL,lease_until=NULL,
  row_version=#{nextVersion},updated_at=#{now}
  WHERE tenant_id=#{tenant} AND resource_id=#{resource} AND desired_version=#{desired} AND lease_fence=#{fence} AND row_version=#{version}
   AND status='PROCESSING' AND lease_owner=#{owner} AND lease_until>#{now}
